#include <iostream>
using namespace std;
class Stack {
    static const int N = 100;
    int a[N];
    int top;
public:
    Stack() : top(-1) {}
    bool push(int x) {
        if (top == N-1) return false;
        a[++top] = x;
        return true;
    }
    bool pop(int &x) {
        if (top == -1) return false;
        x = a[top--];
        return true;
    }
};
int main() {
    Stack s; int x;
    s.push(10); s.push(20);
    if (s.pop(x)) cout << x << '\n';
    return 0;
}

