#include <stdio.h>
int main(void)
{
    FILE *src = fopen("input.txt", "r");
    FILE *dst;
    int ch;
    if (src == NULL) {
        perror("input.txt");
        return 1;
    }
    dst = fopen("output.txt", "w");
    if (dst == NULL) {
        perror("output.txt");
        fclose(src);
        return 1;
    }
    while ((ch = fgetc(src)) != EOF) {
        if (fputc(ch, dst) == EOF) {
            perror("write error");
            fclose(src);
            fclose(dst);
            return 1;
        }
    }
    if (ferror(src)) perror("read error");
    fclose(src);
    fclose(dst);
    return 0;
}

